package org.evox.spen.compat;
import android.content.ComponentName;import android.os.*;import java.lang.reflect.*;import java.util.*;import java.util.regex.*;
/** Feed the original ActivitySwitchDetector; retain its rule selection and listener dispatch. */
public final class TaskAccess {
 private static final Map<Object,Thread> workers=new IdentityHashMap<>();private static final Handler main=new Handler(Looper.getMainLooper());private static volatile ComponentName latest;private static volatile int latestTask=-1;
 public static ComponentName latest(){return latest;}
 /** No foreground component is a valid startup state; empty metadata cannot match a real app rule. */
 public static String className(ComponentName component){return component==null?"":component.getClassName();}
 public static String packageName(ComponentName component){return component==null?"":component.getPackageName();}
 public static synchronized void register(final Object listener){if(workers.containsKey(listener))return;final Object detector;try{detector=listener.getClass().getField("a").get(listener);}catch(ReflectiveOperationException e){throw new IllegalStateException("Original task listener layout changed",e);}Thread worker=new Thread(()->{ComponentName previous=null;int cycle=0;while(!Thread.currentThread().isInterrupted()){try{String state=RootAccess.run("dumpsys activity activities | grep -m 1 'topResumedActivity='  ");Matcher component=Pattern.compile(" ([A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+) ").matcher(state);if(component.find()){ComponentName current=ComponentName.unflattenFromString(component.group(1));Matcher task=Pattern.compile(" t([0-9]+)").matcher(state);int id=task.find()?Integer.parseInt(task.group(1)):-1;latest=current;latestTask=id;if(current!=null&&!current.equals(previous)){previous=current;main.post(()->publish(listener,detector,current,id));}}if(cycle++%5==0)DisplayAccess.refresh();Thread.sleep(600);}catch(InterruptedException stopped){Thread.currentThread().interrupt();}catch(Exception failure){android.util.Log.w("AirCommandPort","Original foreground monitor: "+failure.getClass().getSimpleName());try{Thread.sleep(1500);}catch(InterruptedException stopped){Thread.currentThread().interrupt();}}}},"AirCommand-original-foreground");worker.setDaemon(true);workers.put(listener,worker);worker.start();android.util.Log.i("AirCommandPort","Original task listener connected to in-package foreground monitor");}
 private static void publish(Object listener,Object detector,ComponentName component,int task){synchronized(TaskAccess.class){if(!workers.containsKey(listener))return;}try{Class<?> type=detector.getClass();Object lock=type.getField("f").get(detector);synchronized(lock){type.getField("c").set(detector,component);type.getField("d").setInt(detector,task);}Class<?> cache=Class.forName("b2.a",false,type.getClassLoader());cache.getField("h").set(null,component.getPackageName());type.getMethod("a",type).invoke(null,detector);android.util.Log.d("AirCommandPort","Original foreground rule listeners updated");}catch(ReflectiveOperationException error){android.util.Log.e("AirCommandPort","Original task callback failed",error);}}
 public static synchronized void unregister(Object listener){Thread worker=workers.remove(listener);if(worker!=null)worker.interrupt();}
 public static ComponentName top(android.content.Context c){RuntimeContext.init(c);if(latest!=null)return latest;try{String state=RootAccess.run("dumpsys activity activities | grep -m 1 topResumedActivity=");Matcher m=Pattern.compile(" ([A-Za-z0-9_.$]+/[A-Za-z0-9_.$]+) ").matcher(state);if(m.find())latest=ComponentName.unflattenFromString(m.group(1));}catch(Exception unavailable){android.util.Log.w("AirCommandPort","Foreground query unavailable");}return latest;}
 public static ComponentName topTask(android.content.Context c,int task){return task==latestTask?top(c):null;}
}
